pub fn choices_key(words: &ProjectWords, bounds: BoundsChecks, overflow: OverflowChecks, skip_free_on: bool, through_loops_on: bool, cpu_key: &str) -> String {
    let tests = if words.tests { "/tests" } else { "" };
    let refuted = if words.refuted_claims == "warn" { "/refuted-claims:warn" } else { "" };
    let unproved = if words.unproved_claims == "warn" { "/unproved-claims:warn" } else { "" };
    let removed_bounds = match bounds {
        BoundsChecks::Kept => String::from(""),
        _ => format!("/remove-bounds-checks:{}", bounds.name()),
    };
    let removed_overflow = match overflow {
        OverflowChecks::Kept => String::from(""),
        _ => format!("/remove-overflow-checks:{}", overflow.name()),
    };
    let skip_free = if skip_free_on { "/skip-free-at-exit:on" } else { "" };
    let through_loops = if through_loops_on { "/prove-through-loops:on" } else { "" };
    let library = if words.artifact == "c-library" { format!("/c-library:{}", words.symbol_prefix) } else { String::from("") };
    let cpu = if words.cpu.is_some() { format!("/cpu:{}", cpu_key) } else { String::from("") };
    format!("{}/{}/{}{}{}{}{}{}{}{}{}{}", words.target, words.user_parallelism, words.reentrancy_check, tests, refuted, unproved, removed_bounds, removed_overflow, skip_free, through_loops, library, cpu)
}

pub fn panic_strategy(target: Target) -> String {
    match target {
        Target::X86_64Linux | Target::Aarch64Linux => String::from("unwind"),
        Target::Wasm32Unknown => String::from("abort"),
        _ => { if target.is_bare_metal() || target.triple().starts_with("wasm") { String::from("abort") } else { String::from("unwind") } },
    }
}

pub fn encoded_with_cpu(encoded: &Option<String>, plain: &Option<String>, cpu: &str) -> Option<String> {
    let mut flags: Vec<String> = match match encoded.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } {
        Some(ref e) => e.split("\x1f").filter(|&f| { !f.is_empty() }).map(|f| { f.to_string() }).collect::<Vec<_>>(),
        None => match match plain.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } {
            Some(ref p) => p.split_whitespace().map(|f| { f.to_string() }).collect::<Vec<_>>(),
            None => return None,
        },
    };
    flags.push(String::from("-C"));
    flags.push(format!("target-cpu={}", cpu));
    Some(flags.join("\x1f"))
}

